// src/kr-districts.js
function line(deltas) {
	let x = 0, y = 0;
	const points = [];
	for (let i = 0; i < deltas.length; i += 2) points.push([(x += deltas[i]) / 1e5, (y += deltas[i + 1]) / 1e5]);
	return points;
}
function ring(deltas) {
	const pts = line(deltas);
	return [...pts, pts[0]];
}
var polygon = (polys) => ({
	type: "MultiPolygon",
	coordinates: polys.map((poly) => poly.map(ring))
});
var decodeKrLines = (province) => ({
	type: "MultiLineString",
	coordinates: JSON.parse(province ? kr_sido_lines_default : kr_sgg_lines_default).map(line)
});
var decodeKrProvinces = () => ({
	type: "FeatureCollection",
	features: JSON.parse(kr_sido_default).map(([code, nameKo, polys]) => ({
		type: "Feature",
		properties: {
			code,
			nameKo
		},
		geometry: polygon(polys)
	}))
});
function decodeKrDistricts() {
	return {
		type: "FeatureCollection",
		features: JSON.parse(kr_districts_default).map(([code, province, name, polys]) => ({
			type: "Feature",
			properties: {
				code,
				nameKo: `${province} ${name}`
			},
			geometry: polygon(polys)
		}))
	};
}
